import frappe
from frappe.utils import flt, getdate


def get_stock_balance(item_code: str, warehouse: str, posting_date=None) -> float:
	"""Quantity of the item in the warehouse on the posting date."""
	result = frappe.db.sql(
		"""SELECT SUM(actual_qty) FROM `tabStock Ledger Entry`
		WHERE item_code = %s AND warehouse = %s AND posting_date <= %s AND is_cancelled = 0""",
		(item_code, warehouse, getdate(posting_date)),
	)
	return flt(result[0][0]) if result else 0.0


def get_valuation_rate(item_code: str, warehouse: str) -> float:
	"""Moving average rate of the item in the warehouse, from the last ledger entry."""
	rate = frappe.db.get_value(
		"Stock Ledger Entry",
		{"item_code": item_code, "warehouse": warehouse, "is_cancelled": 0},
		"valuation_rate",
		order_by="posting_date desc, posting_time desc, creation desc",
	)
	if rate is None:
		rate = frappe.db.get_value("Item", item_code, "valuation_rate")
	return flt(rate)


def get_batch_rate(batch_no: str) -> float:
	"""Incoming rate of the batch, from the receipt that created it."""
	return flt(frappe.db.get_value("Batch", batch_no, "incoming_rate"))

