import frappe
from frappe import _
from frappe.model.document import Document
from frappe.utils import flt

from stockroom.stock import utils as stock_utils


class StockEntry(Document):
	def validate(self):
		self.validate_items()
		self.set_rates()

	def validate_items(self):
		if not self.items:
			frappe.throw(_("Add at least one item"))
		for row in self.items:
			if flt(row.qty) <= 0:
				frappe.throw(_("Row {0}: the quantity must be positive").format(row.idx))
			if self.purpose in ("Material Issue", "Material Transfer") and not row.s_warehouse:
				frappe.throw(_("Row {0}: set the source warehouse").format(row.idx))

	def set_rates(self):
		for row in self.items:
			if not row.s_warehouse:
				# A receipt keeps the rate that the user entered.
				continue
			if row.batch_no:
				# A batch keeps its own cost: the warehouse average mixes it with other batches.
				row.basic_rate = stock_utils.get_batch_valuation_rate(
					row.item_code, row.s_warehouse, row.batch_no, self.posting_date
				)
			else:
				row.basic_rate = stock_utils.get_valuation_rate(row.item_code, row.s_warehouse)
			row.amount = flt(row.basic_rate) * flt(row.qty)
		self.total_amount = sum(flt(row.amount) for row in self.items)

	def on_submit(self):
		for row in self.items:
			if row.s_warehouse:
				self.add_ledger_entry(row, row.s_warehouse, -flt(row.qty))
			if row.t_warehouse:
				self.add_ledger_entry(row, row.t_warehouse, flt(row.qty))

	def add_ledger_entry(self, row, warehouse: str, qty: float):
		frappe.get_doc(
			{
				"doctype": "Stock Ledger Entry",
				"item_code": row.item_code,
				"warehouse": warehouse,
				"batch_no": row.batch_no,
				"actual_qty": qty,
				"incoming_rate": row.basic_rate if qty > 0 else 0,
				"posting_date": self.posting_date,
				"voucher_type": self.doctype,
				"voucher_no": self.name,
			}
		).insert()

